import TextInputForm from '@/components/forms/TextInputForm';
import { Textarea } from '@/components/ui/textarea';
import { FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { UseFormReturn } from 'react-hook-form';
import { AddDepartmentFormValues } from '../schemas/addDepartment/add-department-schema';

const NONE_HEAD = '0';

interface Props {
    form: UseFormReturn<AddDepartmentFormValues>;
    employeeOptions: { name: string; value: string }[];
    /** Shown read-only; updated later by the system */
    currentEmployees: number;
}

export default function PersonalInfo({ form, employeeOptions, currentEmployees }: Props) {
    return (
        <div className="mb-6 grid grid-cols-1 gap-6 md:max-w-2xl">
            <TextInputForm name="name" label="اسم القسم" placeholder="ادخل اسم القسم" />
            <FormField
                control={form.control}
                name="description"
                render={({ field }) => (
                    <FormItem>
                        <FormLabel className="text-primery-blue-900">وصف القسم</FormLabel>
                        <FormControl>
                            <Textarea
                                {...field}
                                value={field.value ?? ''}
                                placeholder="وصف اختياري للقسم..."
                                rows={4}
                                className="resize-y min-h-[100px] border-[#E5E7EB] placeholder:text-[#90868C]"
                            />
                        </FormControl>
                        <FormMessage />
                    </FormItem>
                )}
            />
            <FormField
                control={form.control}
                name="department_head_id"
                render={({ field }) => (
                    <FormItem>
                        <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                            مسؤول القسم (من الموظفين)
                        </FormLabel>
                        <Select onValueChange={field.onChange} value={field.value ?? NONE_HEAD}>
                            <FormControl>
                                <SelectTrigger>
                                    <SelectValue placeholder="اختر موظفاً" />
                                </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                                {employeeOptions.map((o) => (
                                    <SelectItem key={o.value} value={o.value} className="font-cairo">
                                        {o.name}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <FormMessage />
                    </FormItem>
                )}
            />
            <TextInputForm
                name="max_employees"
                label="الحد الأقصى لعدد الموظفين"
                placeholder="مثال: 25"
                type="number"
            />
            <div className="space-y-1.5">
                <label className="text-xs text-[#625E74]">العدد الحالي للموظفين</label>
                <Input
                    readOnly
                    value={String(currentEmployees)}
                    className="h-9 bg-[#F3F4F6] text-[#4B5563]"
                    dir="ltr"
                />
                <p className="text-[11px] text-[#90868C]">يُحدَّث تلقائياً لاحقاً حسب بيانات الموظفين</p>
            </div>
        </div>
    );
}
