import PersonalInfo from './PersonalInfo';
import MainHeading from '@/components/heading/MainHeading';

import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import Submission from './Submission';
import { Department } from '@/types/department.types';
import {
    AddDepartmentFormValues,
    AddDepartmentSchema,
    headIdForApi,
} from '../schemas/addDepartment/add-department-schema';

interface Props {
    department?: Department | null;
}

const NONE_HEAD = '0';

export default function AddDepartmentForm({ department }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);
    const [employeeOptions, setEmployeeOptions] = useState<{ name: string; value: string }[]>([
        { name: '— بدون —', value: NONE_HEAD },
    ]);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.employee.simpleList });
                const rows = res.data?.data;
                const list = Array.isArray(rows)
                    ? rows.map((e: { id: number; name: string }) => ({
                          name: e.name ?? `موظف #${e.id}`,
                          value: String(e.id),
                      }))
                    : [];
                setEmployeeOptions([{ name: '— بدون —', value: NONE_HEAD }, ...list]);
            } catch {
                setEmployeeOptions([{ name: '— بدون —', value: NONE_HEAD }]);
            }
        };
        void load();
    }, []);

    const defaultValues = useMemo(
        () => ({
            name: department?.name ?? '',
            description: department?.description ?? '',
            department_head_id: department?.department_head_id ? String(department.department_head_id) : NONE_HEAD,
            max_employees: department?.max_employees != null && department.max_employees >= 1 ? department.max_employees : 10,
        }),
        [department],
    );

    const form = useForm<AddDepartmentFormValues>({
        resolver: zodResolver(AddDepartmentSchema),
        defaultValues,
    });

    useEffect(() => {
        if (department) {
            form.reset({
                name: department.name ?? '',
                description: department.description ?? '',
                department_head_id: department.department_head_id ? String(department.department_head_id) : NONE_HEAD,
                max_employees:
                    department.max_employees != null && department.max_employees >= 1 ? department.max_employees : 10,
            });
        }
    }, [department, form]);

    const onSubmit = async (data: AddDepartmentFormValues) => {
        setLoading(true);
        setError(null);
        const body = {
            name: data.name.trim(),
            description: data.description?.trim() ? data.description.trim() : null,
            department_head_id: headIdForApi(data.department_head_id),
            max_employees: data.max_employees,
        };
        try {
            await apiPost({
                endpoint: department ? `${endpoints.departments.update}${department.id}` : endpoints.departments.create,
                body,
            });
            setShowSuccessPopup(true);
        } catch (error: unknown) {
            const err = error as { response?: { data?: { errors?: Record<string, string[]>; msg?: string } } };
            if (err.response?.data?.errors) {
                Object.entries(err.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as keyof AddDepartmentFormValues, {
                        type: 'manual',
                        message: messages.join(', '),
                    });
                });
            } else {
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (err.response?.data?.msg) {
                    errorMessage = err.response.data.msg;
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    const currentEmployees = department?.current_employees ?? 0;

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mb-8">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button type="button" onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div>
                        <MainHeading text="بيانات القسم" />
                        <PersonalInfo
                            form={form}
                            employeeOptions={employeeOptions}
                            currentEmployees={currentEmployees}
                        />
                    </div>
                    <Submission
                        department={department}
                        loading={loading}
                        setShowCancelPopup={setShowCancelPopup}
                        setShowSuccessPopup={setShowSuccessPopup}
                        showCancelPopup={showCancelPopup}
                        showSuccessPopup={showSuccessPopup}
                    />
                </form>
            </Form>
        </>
    );
}
